WITH signups AS (SELECT distinct_id AS uid, min(timestamp) AS signed_up FROM events WHERE event='signup_verified' AND (properties.environment = 'production' AND properties.product = 'studio') AND {filters} GROUP BY uid), actions AS (SELECT distinct_id AS uid, timestamp FROM events WHERE (properties.environment = 'production' AND properties.product = 'studio') AND (event IN ('native_media_imported','native_export_completed') OR (event='product_action_completed' AND properties.action IN ('idea_created','content_created','script_generated','canvas_generated','brain_ingested','caption_generated')))), matched AS (SELECT s.uid AS uid, s.signed_up AS signed_up, countIf(a.timestamp>=s.signed_up AND a.timestamp<s.signed_up+INTERVAL 7 DAY) AS activated FROM signups s LEFT JOIN actions a ON s.uid=a.uid GROUP BY s.uid,s.signed_up) SELECT toDate(signed_up) AS Cohort, count() AS Signups, countIf(activated>0) AS Activated, round(100.0*countIf(activated>0)/nullIf(count(),0),1) AS Percent FROM matched GROUP BY Cohort ORDER BY Cohort LIMIT 1000
